const event = $json.body ?? $json;
if (event.type !== 'whatsapp.inbound_message.received') return [];
const msg = event.whatsappInboundMessage ?? {};
const type = msg.type ?? 'unknown';
const input = type === 'text' ? msg.text?.body : type === 'image' ? msg.image?.caption ?? 'ticket' : type === 'location' ? msg.location?.address ?? msg.location?.name : '';
const mediaUrl = type === 'image' ? msg.image?.link : type === 'document' ? msg.document?.link : null;
return [{json:{event_id:event.id,from:msg.from,to:msg.to,customer_name:msg.customerProfile?.name ?? 'Lia',message_type:type,input,media_url:mediaUrl,media_type:msg.image?.mime_type ?? msg.document?.mime_type ?? null}}];

const data = $json;
let reply;
if (data.message_type === 'image' || data.message_type === 'document') {
  reply = 'Recibi tu ticket. Lo guarde para actualizar la despensa y te voy a pedir confirmacion antes de descontar o agregar productos.';
} else if (data.message_type === 'location') {
  reply = 'Ubicacion recibida. La voy a usar para comparar supermercados cercanos y sumar el costo real del traslado.';
} else {
  const text = String(data.input ?? '').toLowerCase();
  reply = text.includes('oferta') || text.includes('compr')
    ? 'La mejor opcion de la prueba es El Dorado: queda a 900 metros y la canasta estimada cuesta $1.086.'
    : text.includes('venc') || text.includes('primero')
      ? 'Usa primero pollo, tomate y palta. Guarda el pollo crudo sellado en el estante inferior.'
      : 'Hoy podes preparar omelette con tomate o pollo con arroz, tomate y palta. ¿Cual preferis?';
}
return [{json:{...data,reply,ycloud_request:{from:data.to,to:data.from,type:'text',text:{body:reply,preview_url:false}}}}];
